-- =============================================================================
-- Relecture complète, vague 1 (groupes soumis à la CSRD) : obligations lues dans les rapports
-- -----------------------------------------------------------------------------
-- Obligations de publication sans preuve en base : chaque rapport réglementé a été lu
-- (relecture complète, PLAN_REFONTE.md). Résultats consignés au journal :
--   absence_confirmee : l'entreprise déclare ne pas publier, ou rien n'est publié (lecture) ;
--   autre_forme       : publié, mais pas sous la forme exigée (sous-périmètre, par zone,
--                       écart ajusté au lieu de non corrigé…) — information affichée telle quelle ;
--   trouvee           : donnée présente, preuve ajoutée (en attente de validation).
-- Le résultat « autre_forme » est ajouté à la liste des résultats possibles.
-- =============================================================================

alter table indicator_reviews drop constraint if exists indicator_reviews_outcome_check;
alter table indicator_reviews add constraint indicator_reviews_outcome_check check (outcome in (
  'confirmee', 'ecart', 'source_inaccessible', 'non_verifiable', 'trouvee', 'absence_confirmee',
  'non_trouvee', 'autre_forme'));

insert into indicator_reviews (entity_id, indicator_id, outcome, detail, source_url, reviewer, wave)
select en.id, i.id, v.outcome, v.detail, v.url, 'relecture:lecture-rapport', 1
from (values
  ('hermes', 'LAB_GENDER_PAYGAP', 'absence_confirmee', 'Hermès déclare ne pas publier l''écart de rémunération non corrigé exigé (S1-16 §97 a) ; il publie un écart ajusté de 2,79 %. Citation : « Hermès a également indiqué dans le présent état de durabilité ne pas être en mesure de chiffrer certains points de données tels que requis par les ESRS, dont les principaux sont : les ressources entrantes liées aux produits finis (E5-4-31) et l’écart de rémunération entre femmes et hommes (S1-16-97) »', 'https://bdif.amf-france.org/back/api/v1/documents/2026/D.26-0114/CBBDE3794700DA7CCD45B4EF4EC18BC78AFEB3BC39486E92A101A56035A54D24.zip'),
  ('carrefour', 'LAB_CEO_PAY_RATIO', 'absence_confirmee', 'Carrefour déclare ne pas publier le ratio exigé (S1-16 §97 b) ; il publie un ratio limité aux salariés du siège. Citation : « concernant le ratio d’équité ou ratio de la plus haute rémunération par rapport à la rémunération médiane (ESRS S1 S1-16 §97b) : Carrefour n’est pas en mesure de publier cette information n’ayant pas de système centralisé permettant de calculer un salaire médian au niveau du Groupe. »', 'https://bdif.amf-france.org/back/api/v1/documents/2026/D.26-0143/7A3CB233AA8727B6F5EE7B409F80D8CBC4ECFCF43ACB2FA1B88354B4090AB39A.zip'),
  ('societe-generale', 'ENV_GHG_INTENSITY', 'absence_confirmee', 'Société Générale déclare ne pas publier l''intensité de GES par chiffre d''affaires net (E1-6 §53), en motivant ce choix. Citation : « Le ratio d’intensité des GES sur la base du chiffre d’affaires net n’est pas publié. Il n’y a aucune corrélation entre le total des émissions de GES et le chiffre d’affaires (PNB) global du Groupe. »', 'https://filings.xbrl.org/O2RNE8IBXP4R0TD8PU41/2025-12-31/ESEF/FR/0/O2RNE8IBXP4R0TD8PU41-2025-12-31-1-FR/reports/O2RNE8IBXP4R0TD8PU41-2025-12-31-1-FR.xhtml'),
  ('bpce', 'ENV_GHG_INTENSITY', 'absence_confirmee', 'Rapport réglementé 2025 lu (recherches : « intensité des émissions de GES », « par chiffre d''affaires net », « tCO2e/M€ ») : aucune intensité de GES par chiffre d''affaires net ; seules des intensités de portefeuilles (assurance, gestion d''actifs) sont publiées.', 'https://filings.xbrl.org/9695005MSX1OYEMGDF46/2025-12-31/ESEF/FR/0/9695005MSX1OYEMGDF46-2025-12-31-1-FR/reports/9695005MSX1OYEMGDF46-2025-12-31-1-FR.xhtml'),
  ('bnp-paribas', 'ENV_GHG_INTENSITY', 'absence_confirmee', 'Rapport réglementé 2025 lu (recherches : « intensité des émissions de GES », « par chiffre d''affaires net », « par million d''euros ») : aucune intensité de GES par chiffre d''affaires net ; seuls des objectifs d''intensité par secteur financé sont publiés.', 'https://filings.xbrl.org/R0MUWSFPU8MPRO8K5P83/2025-12-31/ESEF/FR/1/bnp-2025-12-31-1/reports/bnp-2025-12-31-1-fr.html'),
  ('credit-agricole', 'ENV_GHG_INTENSITY', 'autre_forme', 'Publié sous une autre forme : intensité carbone des encours (411 teqCO2 par million d''euros prêté), et non par chiffre d''affaires net (E1-6 §53). Citation : « Émissions de GES liées aux financements Unité 2025 2024 Total des émissions financées teqCO 2 165 576 282 164 107 508 Intensité carbone des encours teqCO 2 /M€ 411 414 »', 'https://filings.xbrl.org/969500TJ5KRTCJQWXH05/2025-12-31/ESEF/FR/0/969500TJ5KRTCJQWXH05-2025-12-31-1-fr/reports/969500TJ5KRTCJQWXH05-2025-12-31-1-fr.xhtml'),
  ('loreal', 'LAB_GENDER_PAYGAP', 'autre_forme', 'Publié sous une autre forme : deux écarts bruts par population (2,5 % hors conseiller(ère)s de beauté, −1,6 % pour elles seules), sans chiffre pour l''ensemble du groupe. Citation : « Écart brut de rémunération entre les femmes et les hommes, en pourcentage du niveau de rémunération moyen des travailleurs hommes (1) - excluant les conseiller(ère)s de beauté 2,9 % 2,5 % Écart brut de rémunération entre les femmes et les hommes, en pourcentage du niveau de rémunération moyen des travailleurs hommes (1) - uniquement pour les conseiller(ère)s de beauté - 9,2 % - 1,6 % (2) »', 'https://filings.xbrl.org/529900JI1GG6F7RKVI53/2025-12-31/ESEF/FR/0/loreal-2025-12-31-1-fr/reports/loreal-2025-12-31-1-fr.xhtml'),
  ('loreal', 'LAB_CEO_PAY_RATIO', 'autre_forme', 'Publié sous une autre forme : un ratio par zone (Europe 196, Amérique latine 71, Amérique du Nord 45, Asie du Nord 80, SAPMENA-SSA 82), sans ratio pour l''ensemble du groupe. Citation : « Ratio de rémunération annuelle totale de la personne la plus payée par rapport à la rémunération totale annuelle médiane de tous les salariés (à l’exclusion de la personne la mieux rémunérée) (1) par Zone : 2024 2025 Europe 179 196 Amérique Latine 67 71 Amérique du Nord 49 45 Asie du Nord 70 80 SAPMENA & SSA 88 82 »', 'https://filings.xbrl.org/529900JI1GG6F7RKVI53/2025-12-31/ESEF/FR/0/loreal-2025-12-31-1-fr/reports/loreal-2025-12-31-1-fr.xhtml'),
  ('totalenergies', 'LAB_GENDER_PAYGAP', 'autre_forme', 'Publié sous une autre forme : écart ajusté (2,9 % en faveur des hommes) ; l''écart non corrigé exigé (S1-16 §97 a) n''a pas été trouvé. Citation : « En 2025, l’écart de rémunération ajusté global (388) est de 2,9% en faveur des hommes en rémunération directe »', 'https://filings.xbrl.org/529900S21EQ1BO4ESM68/2025-12-31/ESEF/FR/0/529900S21EQ1BO4ESM68-2025-12-31-1-fr/reports/529900S21EQ1BO4ESM68-2025-12-31-1-fr.xhtml'),
  ('totalenergies', 'LAB_CEO_PAY_RATIO', 'autre_forme', 'Publié sous une autre forme : ratios pour la France seulement (TotalEnergies SE, et périmètre couvrant 80 % de la masse salariale France : 116 en 2025), pas pour l''ensemble du groupe. Citation : « Ratio par rapport à la rémunération médiane des salariés 77 86 101* 118 116 »', 'https://filings.xbrl.org/529900S21EQ1BO4ESM68/2025-12-31/ESEF/FR/0/529900S21EQ1BO4ESM68-2025-12-31-1-fr/reports/529900S21EQ1BO4ESM68-2025-12-31-1-fr.xhtml'),
  ('bpce', 'LAB_GENDER_PAYGAP', 'autre_forme', 'Publié sous une autre forme : deux écarts (16,7 % hors Natixis, 34,6 % pour Natixis), sans chiffre pour l''ensemble du groupe. Citation : « l''écart de rémunération entre les hommes et les femmes sur le périmètre du Groupe BPCE hors Natixis est de 16,7 %. Sur le périmètre Natixis, l''écart est de 34,6 % »', 'https://filings.xbrl.org/9695005MSX1OYEMGDF46/2025-12-31/ESEF/FR/0/9695005MSX1OYEMGDF46-2025-12-31-1-FR/reports/9695005MSX1OYEMGDF46-2025-12-31-1-FR.xhtml'),
  ('bnp-paribas', 'LAB_CEO_PAY_RATIO', 'autre_forme', 'Publié sous une autre forme : un ratio par pays (France 110, Royaume-Uni 86, Turquie 75…), sans ratio pour l''ensemble du groupe. Citation : « RATIO DE LA RÉMUNÉRATION LA PLUS ÉLEVÉE PAR RAPPORT À LA MÉDIANE (135) Ratio par pays 2025 2024 France 110 91 BNP Paribas SA (1) en France 83 79 Italie 48 44 Inde 51 52 Belgique 19 19 Pologne 38 40 Portugal 20 21 Turquie 75 76 Royaume-Uni 86 84 Allemagne 34 28 Espagne 45 44 »', 'https://filings.xbrl.org/R0MUWSFPU8MPRO8K5P83/2025-12-31/ESEF/FR/1/bnp-2025-12-31-1/reports/bnp-2025-12-31-1-fr.html'),
  ('hm-group', 'LAB_GENDER_PAYGAP', 'trouvee', 'Donnée trouvée : rémunération des femmes = 99,7 % de celle des hommes, soit un écart de 0,3 % en faveur des hommes ; preuve ajoutée, en attente de validation par l''éditeur (conversion). Citation : « The gender pay gap, expressed as a percentage of the average pay level of male employees, amounted to 99.7 percent »', 'https://hmgroup.com/wp-content/uploads/2026/03/HM-Group-Annual-and-sustainability-report-2025.pdf')
) as v(slug, code, outcome, detail, url)
join entities en on en.slug = v.slug
join indicators i on i.code = v.code;
